window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4e6d587df6cf09a4"]={"versions": [{"id": "FIG-4e6d587df6cf09a4", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Ressourcen-Metamodells in AUTOSAR (ResourceTemplateECU). Das Diagramm modelliert die strukturellen Eigenschaften von physisch bereitgestellten Speichersegmenten (<code>ProvidedMemorySegment</code>), deren Spezialisierung als nichtflüchtiger Speicher sowie deren Anbindung an speicherabgebildete Hardwareschnittstellen (<code>MemoryMappedHWPort</code>) und Mechanismen zur Fehlererkennung und -korrektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong>HWElement</strong>: Abstrakte Basisklasse für Hardwareelemente.\n</li><li><strong>ProvidedMemorySegment</strong> (spezialisiert <code>HWElement</code>): Repräsentiert ein bereitgestelltes Speichersegment mit den Attributen:\n<ul class=\"fig-list\"><li><code>+ segmentSize: Int</code>: Größe des Segments.\n</li><li><code>+ alignment: Int [0..1]</code>: Ausrichtungsvorgabe in Bytes.\n</li><li><code>+ separate: Boolean [0..1]</code>: Kennzeichnung separater Speicherbereiche.\n</li><li><code>+ manufacturingQuality: Float [0..1]</code>: Fertigungsqualität des Speichers.\n</li></ul>\n</li><li><strong>ProvidedNVMemorySegment</strong> (spezialisiert <code>ProvidedMemorySegment</code>): Spezialisierung für nichtflüchtige Speichersegmente mit den Attributen:\n<ul class=\"fig-list\"><li><code>+ segmentSizeWrite: Int [0..1]</code>: Blockgröße für Schreiboperationen.\n</li><li><code>+ segmentSizeErase: Int [0..1]</code>: Blockgröße für Löschoperationen.\n</li><li><code>+ dataRetention: Float [0..1]</code>: Datenerhaltungsdauer.\n</li><li><code>+ dataEndurance: Int [0..1]</code>: Schreib-/Löschzyklenfestigkeit.\n</li><li><code>+ marginReadAvailable: Boolean [0..1]</code>: Verfügbarkeit von Margin-Read-Operationen.\n</li></ul>\n</li><li><strong>ErrorDetectionCorrection</strong>: Spezifiziert Merkmale zur Fehlererkennung/-korrektur:\n<ul class=\"fig-list\"><li><code>+ extraBits: Int</code>: Zusätzliche Bits für Prüfsummen/ECC.\n</li><li><code>+ detectedBits: Int</code>: Anzahl detektierbarer Bitfehler.\n</li><li><code>+ correctedBits: Int</code>: Anzahl korrigierbarer Bitfehler.\n</li><li>Kompositionsbeziehung: <code>ProvidedMemorySegment</code> aggregiert per Komposition <code>0..1</code> Instanzen von <code>ErrorDetectionCorrection</code> über die Rollenbezeichnung <code>+architecturalQuality</code>.\n</li></ul>\n</li><li><strong>HWPort</strong> (spezialisiert <code>Identifiable</code>): Basisklasse für Hardware-Ports.\n</li><li><strong>MemoryMappedHWPort</strong> (spezialisiert <code>HWPort</code>): Speicherabgebildeter Port mit den Attributen:\n<ul class=\"fig-list\"><li><code>+ dataInterfaceWidth: Int</code>: Datenbusbreite.\n</li><li><code>+ hwPortType: Enumeration{unspecified, data, control}</code>: Typ des Ports.\n</li><li>Assoziation: Gerichtete Assoziation von <code>ProvidedMemorySegment</code> zu <code>MemoryMappedHWPort</code> über die Assoziationsrolle <code>memoryHWPorts</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein strukturelles Metamodell-Klassendiagramm enthält das Diagramm keine Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt statische Deklarationen von Hardware-Ressourcen für Konfigurations- und Generierungswerkzeuge.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen dienen der formalen Beschreibung der ECU-Hardwareressourcen in AUTOSAR ECU Resource Descriptions. Die Attribute steuern unter anderem Speicherallokation, Alignment-Prüfungen des Linkers, Zugriffsbreiten im Memory Mapping sowie Flash/NVRAM-Treiberparameter (z. B. Sektorengrößen für Lösch- und Programmieroperationen). Optionale Attribute (<code>[0..1]</code>) müssen von Werkzeugen mit Standardannahmen behandelt werden, falls sie in der Ressourcenbeschreibung nicht instantiiert sind.</p>"}, {"id": "FIG-b4fec73785fa7c80", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Ressourcen-Metamodells in AUTOSAR (ResourceTemplateECU). Das Diagramm modelliert die strukturellen Eigenschaften von physisch bereitgestellten Speichersegmenten (<code>ProvidedMemorySegment</code>), deren Spezialisierung als nichtflüchtiger Speicher sowie deren Anbindung an speicherabgebildete Hardwareschnittstellen (<code>MemoryMappedHWPort</code>) und Mechanismen zur Fehlererkennung und -korrektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong>HWElement</strong>: Abstrakte Basisklasse für Hardwareelemente.\n</li><li><strong>ProvidedMemorySegment</strong> (spezialisiert <code>HWElement</code>): Repräsentiert ein bereitgestelltes Speichersegment mit den Attributen:\n<ul class=\"fig-list\"><li><code>+ segmentSize: Int</code>: Größe des Segments.\n</li><li><code>+ alignment: Int [0..1]</code>: Ausrichtungsvorgabe in Bytes.\n</li><li><code>+ separate: Boolean [0..1]</code>: Kennzeichnung separater Speicherbereiche.\n</li><li><code>+ manufacturingQuality: Float [0..1]</code>: Fertigungsqualität des Speichers.\n</li></ul>\n</li><li><strong>ProvidedNVMemorySegment</strong> (spezialisiert <code>ProvidedMemorySegment</code>): Spezialisierung für nichtflüchtige Speichersegmente mit den Attributen:\n<ul class=\"fig-list\"><li><code>+ segmentSizeWrite: Int [0..1]</code>: Blockgröße für Schreiboperationen.\n</li><li><code>+ segmentSizeErase: Int [0..1]</code>: Blockgröße für Löschoperationen.\n</li><li><code>+ dataRetention: Float [0..1]</code>: Datenerhaltungsdauer.\n</li><li><code>+ dataEndurance: Int [0..1]</code>: Schreib-/Löschzyklenfestigkeit.\n</li><li><code>+ marginReadAvailable: Boolean [0..1]</code>: Verfügbarkeit von Margin-Read-Operationen.\n</li></ul>\n</li><li><strong>ErrorDetectionCorrection</strong>: Spezifiziert Merkmale zur Fehlererkennung/-korrektur:\n<ul class=\"fig-list\"><li><code>+ extraBits: Int</code>: Zusätzliche Bits für Prüfsummen/ECC.\n</li><li><code>+ detectedBits: Int</code>: Anzahl detektierbarer Bitfehler.\n</li><li><code>+ correctedBits: Int</code>: Anzahl korrigierbarer Bitfehler.\n</li><li>Kompositionsbeziehung: <code>ProvidedMemorySegment</code> aggregiert per Komposition <code>0..1</code> Instanzen von <code>ErrorDetectionCorrection</code> über die Rollenbezeichnung <code>+architecturalQuality</code>.\n</li></ul>\n</li><li><strong>HWPort</strong> (spezialisiert <code>Identifiable</code>): Basisklasse für Hardware-Ports.\n</li><li><strong>MemoryMappedHWPort</strong> (spezialisiert <code>HWPort</code>): Speicherabgebildeter Port mit den Attributen:\n<ul class=\"fig-list\"><li><code>+ dataInterfaceWidth: Int</code>: Datenbusbreite.\n</li><li><code>+ hwPortType: Enumeration{unspecified, data, control}</code>: Typ des Ports.\n</li><li>Assoziation: Gerichtete Assoziation von <code>ProvidedMemorySegment</code> zu <code>MemoryMappedHWPort</code> über die Assoziationsrolle <code>memoryHWPorts</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein strukturelles Metamodell-Klassendiagramm enthält das Diagramm keine Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt statische Deklarationen von Hardware-Ressourcen für Konfigurations- und Generierungswerkzeuge.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen dienen der formalen Beschreibung der ECU-Hardwareressourcen in AUTOSAR ECU Resource Descriptions. Die Attribute steuern unter anderem Speicherallokation, Alignment-Prüfungen des Linkers, Zugriffsbreiten im Memory Mapping sowie Flash/NVRAM-Treiberparameter (z. B. Sektorengrößen für Lösch- und Programmieroperationen). Optionale Attribute (<code>[0..1]</code>) müssen von Werkzeugen mit Standardannahmen behandelt werden, falls sie in der Ressourcenbeschreibung nicht instantiiert sind.</p>"}], "trans": [{"from": "FIG-4e6d587df6cf09a4", "to": "FIG-b4fec73785fa7c80", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Bildbeschnitt / Darstellungsbereich</strong>: Der untere Bereich des Klassendiagramms mit der Klasse <code>ProvidedNVMemorySegment</code> ist nach unten hin abgeschnitten, sodass die Attribute von <code>ProvidedNVMemorySegment</code> (<code>segmentSizeWrite</code>, <code>segmentSizeErase</code>, <code>dataRetention</code>, <code>dataEndurance</code>, <code>marginReadAvailable</code>) nur noch teilweise am unteren Rand sichtbar bzw. abgeschnitten sind.\n</li><li><strong>ProvidedNVMemorySegment</strong>: Der Klassenname im Diagramm wurde typografisch korrigiert (Schreibfehler <code>Prov idedNVMemorySegment</code> korrigiert zu <code>ProvidedNVMemorySegment</code>).\n</li></ul>"}]};
